-- paperclip:migration-safety-ignore large-create-index-not-concurrently: Drizzle migrations run transactionally, so CONCURRENTLY is unavailable. This release introduces the execution-workspace-remediation key namespace, so deployed databases have no matching rows before this required atomic idempotency guard is added.
CREATE UNIQUE INDEX "agent_wakeup_requests_execution_workspace_remediation_idempotency_uq" ON "agent_wakeup_requests" USING btree ("company_id","idempotency_key") WHERE "agent_wakeup_requests"."idempotency_key" LIKE 'execution-workspace-remediation:%' AND "agent_wakeup_requests"."status" <> 'skipped';
